def _ev_cells(lang, t, f, p):
    from pages18 import rep, usd, kk
    s = rep(p); e = s.get("eval") or {}
    tag = "" if s["size"] == 50000 else f" ({kk(s['size'])})"
    a = f"{usd(e['target'], lang)} = {e['target'] / R1:g}R{tag}" if e.get("target") else "—"
    b = f"{usd(e['dd'], lang)} → {int(e['dd'] // DSTOP)}{tag}" if e.get("dd") else "—"
    return a, b

def page_gp_eval(lang, t):
    import ui
    from pages19 import _table, _firm_rows, _checked_note
    table = _table(lang, t, *EV_HEADS, _firm_rows(lang, t, lambda f, p: _ev_cells(lang, t, f, p)))
    top = ui.sec(ui.head(t, None, T("Every firm’s evaluation, in R.","L’évaluation de chaque firme, en R.","La evaluación de cada firma, en R."),
                         T(f"At 50K, with 1R = ${R1} and a daily stop of ${DSTOP}: how far the target is, and how many bad days the max loss absorbs.",
                           f"À 50K, avec 1R = {R1} $ et un stop du jour de {DSTOP} $ : la distance de l’objectif, et combien de mauvaises journées la perte max absorbe.",
                           f"Con 50K, 1R = {R1} $ y un stop diario de {DSTOP} $: lo lejos que está el objetivo y cuántos días malos absorbe la pérdida máxima."))
                 + table + f'<p class="fine vs-note" style="margin-top:20px">{_checked_note(lang, t)}</p>', "t", "firms")
    return _sat_page(lang, t, T("Prop firm evaluation","Évaluation prop firm","Evaluación de prop firm"),
        T("Pass your evaluation with a plan, not with speed.","Réussis ton évaluation avec un plan, pas avec de la vitesse.","Aprueba tu evaluación con un plan, no con velocidad."),
        T("Four numbers decide how you trade an evaluation: your target in R, a daily stop, a daily cap and the bad days your max loss can absorb. Here they are for every firm, checked every week.",
          "Quatre chiffres décident de ta façon de trader une évaluation : ton objectif en R, un stop du jour, un plafond du jour et les mauvaises journées que ta perte max peut absorber. Les voici pour chaque firme, vérifiés chaque semaine.",
          "Cuatro cifras deciden cómo operas una evaluación: tu objetivo en R, un stop diario, un tope diario y los días malos que tu pérdida máxima puede absorber. Aquí están para cada firma, revisadas cada semana."),
        t(EV_BODY), EV_FAQ, [GP_MONTHS[2], "prop-firm-drawdown-rules.html", "prop-firm-consistency-rules.html"],
        T("How to Pass a Prop Firm Evaluation: The Plan · Sweep","Réussir une évaluation prop firm : le plan · Sweep","Cómo aprobar una evaluación de prop firm · Sweep"),
        T("How to pass a prop firm evaluation: your target in R, a daily stop, a daily cap from the consistency rule, and the bad days your max loss can absorb.",
          "Réussir une évaluation prop firm : ton objectif en R, un stop du jour, un plafond tiré de la consistance, et les mauvaises journées que ta perte max absorbe.",
          "Cómo aprobar una evaluación de prop firm: tu objetivo en R, un stop diario, un tope según la consistencia y los días malos que absorbe tu pérdida máxima."),
        "signup_gameplan_eval", top)

# ---- when to size up: the ladder, the drawdown test, the step-down signals
def page_gp_size(lang, t):
    H = lambda x: f"<h2>{t(x)}</h2>"
    body = (H(T("The size ladder","L’échelle de taille","La escalera de tamaño")) + _tbl(t, LADDER) + f'<p>{t(T("Every account, and every new month, starts at step 1.","Chaque compte, et chaque nouveau mois, commence à l’étape 1.","Cada cuenta, y cada mes nuevo, empieza en el peldaño 1."))}</p>'
            + H(T("The drawdown test","Le test du drawdown","La prueba del drawdown")) + f'<p>{t(T("Before each step up, check that your distance to the max loss still holds at least 2 full days of your daily stop at the new size. Example: with $1,200 left before the max loss and a daily stop of $100 at 1 micro, you can absorb 12 bad days. At 3 micros, the daily stop is $300: 4 days, still above 2. With $500 left, 3 micros means less than 2 days: stay at your step, or step down.","Avant chaque étape, vérifie que ta distance à la perte max contient encore au moins 2 journées complètes de ton stop du jour à la nouvelle taille. Exemple : avec 1 200 $ avant la perte max et un stop du jour de 100 $ à 1 micro, tu peux absorber 12 mauvaises journées. À 3 micros, le stop du jour est de 300 $ : 4 journées, toujours plus de 2. Avec 500 $ restants, 3 micros donnent moins de 2 journées : reste à ton étape, ou redescends.","Antes de cada peldaño, comprueba que tu distancia a la pérdida máxima aún cubre al menos 2 días completos de tu stop diario con el nuevo tamaño. Ejemplo: con 1.200 $ antes de la pérdida máxima y un stop diario de 100 $ con 1 micro, puedes absorber 12 días malos. Con 3 micros, el stop diario es de 300 $: 4 días, todavía más de 2. Con 500 $ restantes, 3 micros dan menos de 2 días: quédate en tu peldaño o baja."))}</p>'
            + H(T("Step down immediately if","Redescends tout de suite si","Baja de inmediato si")) + _ul(t, STEP_DOWN)
            + f'<p class="fine">{t(T("Stepping down is not a punishment. It’s the ladder doing its job: you climb back with the same criteria.","Redescendre n’est pas une punition. C’est l’échelle qui fait son travail : tu remontes avec les mêmes critères.","Bajar no es un castigo. Es la escalera haciendo su trabajo: vuelves a subir con los mismos criterios."))}</p>'
            + H(T("After a pass, a payout or a new account","Après une réussite, un payout ou un nouveau compte","Tras aprobar, un payout o una cuenta nueva")) + f'<p>{t(T("Back to step 1 for 5 sessions. A win changes your account, not your process.","Retour à l’étape 1 pendant 5 séances. Une victoire change ton compte, pas ton processus.","Vuelta al peldaño 1 durante 5 sesiones. Una victoria cambia tu cuenta, no tu proceso."))}</p>'
            + H(T("Micros before minis","Les micros avant les minis","Los micros antes que los minis")) + f'<p>{t(T("One mini (ES, NQ) is worth 10 micros. Climbing from 1 to 3 micros keeps each step small; moving to a mini multiplies the risk by 10 at once. Your firm also caps the number of contracts per account: it’s on <a href=\"@prop-firms/index.html\">each firm’s page</a>.","Un mini (ES, NQ) vaut 10 micros. Monter de 1 à 3 micros garde chaque étape petite ; passer à un mini multiplie le risque par 10 d’un coup. Ta firme limite aussi le nombre de contrats par compte : c’est sur <a href=\"@prop-firms/index.html\">la page de chaque firme</a>.","Un mini (ES, NQ) vale 10 micros. Subir de 1 a 3 micros mantiene cada peldaño pequeño; pasar a un mini multiplica el riesgo por 10 de golpe. Tu firma también limita el número de contratos por cuenta: está en <a href=\"@prop-firms/index.html\">la página de cada firma</a>."))}</p>'
            + H(T("Practice the next step first","Pratique d’abord l’étape suivante","Practica primero el siguiente peldaño")) + f'<p>{t(T("On 10 replay setups, calculate the risk at the next step. If the stop no longer fits your daily stop, the size has to wait, not your limits. The <a href=\"@position-size-calculator.html\">position size calculator</a> does the math.","Sur 10 setups en replay, calcule le risque à l’étape suivante. Si le stop n’entre plus dans ton stop du jour, c’est la taille qui attend, pas tes limites. Le <a href=\"@position-size-calculator.html\">calculateur de taille de position</a> fait le calcul.","En 10 setups en replay, calcula el riesgo en el siguiente peldaño. Si el stop ya no cabe en tu stop diario, es el tamaño el que espera, no tus límites. La <a href=\"@position-size-calculator.html\">calculadora de tamaño de posición</a> hace el cálculo."))}</p>')
    faqs = [(T("How many contracts should I trade on a 50K prop account?","Combien de contrats trader sur un compte prop de 50K ?","¿Cuántos contratos operar en una cuenta prop de 50K?"),
             T("Start with 1 micro, whatever the account size, and let the ladder add the next ones: 10 clean sessions per step, and always 2 full days of daily stop left before the max loss. The account size sets the firm’s limit, not your risk.","Commence avec 1 micro, peu importe la taille du compte, et laisse l’échelle ajouter les suivants : 10 séances propres par étape, et toujours 2 journées complètes de stop du jour avant la perte max. La taille du compte fixe la limite de la firme, pas ton risque.","Empieza con 1 micro, sea cual sea el tamaño de la cuenta, y deja que la escalera añada los siguientes: 10 sesiones limpias por peldaño y siempre 2 días completos de stop diario antes de la pérdida máxima. El tamaño de la cuenta fija el límite de la firma, no tu riesgo.")),
            (T("Should I size up after a big win?","Dois-je augmenter ma taille après un gros gain ?","¿Debo subir el tamaño después de una gran ganancia?"),
             T("No. After a pass, a payout or your best day, the next session is a normal one, at the same size. A win changes your account, not your process.","Non. Après une réussite, un payout ou ta meilleure journée, la séance suivante est normale, à la même taille. Une victoire change ton compte, pas ton processus.","No. Tras aprobar, un payout o tu mejor día, la siguiente sesión es normal, con el mismo tamaño. Una victoria cambia tu cuenta, no tu proceso.")),
            (T("When should I size down?","Quand redescendre ?","¿Cuándo bajar el tamaño?"),
             T("Right away after 2 major slips in 5 sessions, 2 daily stops in a row, or when your distance to the max loss no longer holds 2 full days of daily stop.","Tout de suite après 2 écarts majeurs en 5 séances, 2 stops du jour de suite, ou quand ta distance à la perte max ne contient plus 2 journées complètes de stop du jour.","De inmediato tras 2 deslices graves en 5 sesiones, 2 stops diarios seguidos o cuando tu distancia a la pérdida máxima ya no cubre 2 días completos de stop diario."))]
    return _sat_page(lang, t, T("Position size","Taille de position","Tamaño de posición"),
        T("Size up slowly. Size down instantly.","Monte lentement. Redescends tout de suite.","Sube despacio. Baja al instante."),
        T("When to trade more contracts on a prop firm account: a three-step ladder, the criteria to climb, the drawdown test, and the three signals that take you back down.",
          "Quand trader plus de contrats sur un compte prop : une échelle en trois étapes, les critères pour monter, le test du drawdown, et les trois signaux qui te font redescendre.",
          "Cuándo operar más contratos en una cuenta prop: una escalera de tres peldaños, los criterios para subir, la prueba del drawdown y las tres señales que te hacen bajar."),
        body, faqs, [GP_MONTHS[2], "position-size-calculator.html", "trailing-drawdown-calculator.html"],
        T("When to Size Up on a Prop Firm Account · Sweep","Quand augmenter sa taille en prop firm · Sweep","Cuándo subir el tamaño en una prop firm · Sweep"),
        T("When to trade more contracts on a prop firm account: a 3-step size ladder from 1 to 3 micros, the drawdown test before each step, and when to size down.",
          "Quand trader plus de contrats sur un compte prop : une échelle de 1 à 3 micros, le test du drawdown avant chaque étape, et quand redescendre.",
          "Cuándo operar más contratos en una cuenta prop: una escalera de 1 a 3 micros, la prueba del drawdown antes de cada peldaño y cuándo bajar."),
        "signup_gameplan_size")

# ---- the funded account playbook
def page_gp_funded(lang, t):
    H = lambda x: f"<h2>{t(x)}</h2>"
    body = (H(T("Why funded accounts get lost","Pourquoi les comptes financés se perdent","Por qué se pierden las cuentas financiadas")) + f'<p>{t(T("Two classic mistakes: wanting to maximize once it’s “real”, and dropping the small habits that made the pass: the checklist, the pause after a loss, the journal. The funded account also has its own rules, often different from the evaluation’s: a daily loss limit, a consistency rule, payout conditions.","Deux erreurs classiques : vouloir maximiser une fois que c’est « pour vrai », et laisser tomber les petites habitudes qui ont mené à la réussite : la checklist, la pause après une perte, le journal. Le compte financé a aussi ses propres règles, souvent différentes de celles de l’évaluation : une limite de perte quotidienne, une règle de consistance, des conditions de payout.","Dos errores clásicos: querer maximizar una vez que es «de verdad», y abandonar los pequeños hábitos que llevaron a aprobar: la checklist, la pausa tras una pérdida, el diario. La cuenta financiada también tiene sus propias reglas, a menudo distintas de las de la evaluación: un límite de pérdida diaria, una regla de consistencia, condiciones de payout."))}</p>'
            + H(T("The five rules","Les cinq règles","Las cinco reglas")) + _ol(t, PLAYBOOK)
            + H(T("Your payout rule","Ta règle de payout","Tu regla de payout")) + f'<p>{t(T("Decide it now, inside your firm’s rules: how often you request, how much, and what cushion you keep above the max loss. Each firm’s winning days, cushion, caps and split are in the <a href=\"@prop-firm-payout-rules.html\">payout rules guide</a>, and the <a href=\"@payout-calculator.html\">payout calculator</a> shows what you can request.","Décide-la maintenant, dans les règles de ta firme : à quelle fréquence tu demandes, combien, et quel coussin tu gardes au-dessus de la perte max. Les jours gagnants, le coussin, les plafonds et le partage de chaque firme sont dans le <a href=\"@prop-firm-payout-rules.html\">guide des règles de payout</a>, et le <a href=\"@payout-calculator.html\">calculateur de payout</a> montre ce que tu peux demander.","Decídela ahora, dentro de las reglas de tu firma: cada cuánto pides, cuánto y qué colchón mantienes sobre la pérdida máxima. Los días ganadores, el colchón, los topes y el reparto de cada firma están en la <a href=\"@prop-firm-payout-rules.html\">guía de reglas de payout</a>, y la <a href=\"@payout-calculator.html\">calculadora de payout</a> muestra lo que puedes pedir."))}</p>'
            + H(T("Funded profit is not income","Le profit d’un compte financé n’est pas un revenu","El beneficio de una cuenta financiada no es un ingreso")) + f'<p>{t(T("Until a payout is paid, funded P&L is a balance on the firm’s account, under its rules. Keep evaluation costs, funded results and real payouts apart: that’s your real net. In Sweep, <a href=\"@payout-tracker.html\">My money</a> (Pro) keeps them apart for you.","Tant qu’un payout n’est pas payé, le P&L d’un compte financé est un solde sur le compte de la firme, sous ses règles. Garde à part le coût des évaluations, les résultats des comptes financés et les vrais payouts : c’est ton vrai net. Dans Sweep, <a href=\"@payout-tracker.html\">Mon argent</a> (Pro) les sépare pour toi.","Hasta que se paga un payout, el P&L de una cuenta financiada es un saldo en la cuenta de la firma, bajo sus reglas. Separa el coste de las evaluaciones, los resultados de las cuentas financiadas y los payouts reales: ese es tu neto real. En Sweep, <a href=\"@payout-tracker.html\">Mi dinero</a> (Pro) los separa por ti."))}</p>'
            + H(T("Write yours","Écris les tiens","Escribe los tuyos")) + _ul(t, [T("Your payout rule.","Ta règle de payout.","Tu regla de payout."), T("What you will never change once funded.","Ce que tu ne changeras jamais une fois financé.","Lo que nunca cambiarás una vez financiado."), T("What made you pass, in one sentence.","Ce qui t’a fait réussir, en une phrase.","Lo que te hizo aprobar, en una frase."), T("Your warning sign that you’re drifting.","Ton signal d’alerte que tu dérives.","Tu señal de alerta de que te desvías.")])
            + H(T("Warning signs","Les signaux d’alerte","Las señales de alerta")) + _ul(t, [T("Trading outside your window, or a market you didn’t practice.","Trader hors de ta fenêtre, ou un marché que tu n’as pas pratiqué.","Operar fuera de tu ventana, o un mercado que no practicaste."), T("Size above your step, “just this once”.","Une taille au-dessus de ton étape, « juste cette fois ».","Un tamaño por encima de tu peldaño, «solo esta vez»."), T("Skipping the journal on green days.","Sauter le journal les journées vertes.","Saltarte el diario en los días verdes."), T("Requesting a payout on impulse after a good day.","Demander un payout sur un coup de tête après une bonne journée.","Pedir un payout por impulso después de un buen día.")]))
    faqs = [(T("Why do traders lose funded accounts?","Pourquoi les traders perdent-ils leurs comptes financés ?","¿Por qué los traders pierden sus cuentas financiadas?"),
             T("Usually by changing what got them funded: more size, new setups, no journal. The funded account also often has rules the evaluation didn’t, like a daily loss limit or a consistency rule.","Souvent en changeant ce qui les a fait financer : plus de taille, de nouveaux setups, plus de journal. Le compte financé a aussi souvent des règles que l’évaluation n’avait pas, comme une limite de perte quotidienne ou une règle de consistance.","Normalmente cambiando lo que les hizo conseguir la cuenta: más tamaño, setups nuevos, sin diario. La cuenta financiada también suele tener reglas que la evaluación no tenía, como un límite de pérdida diaria o una regla de consistencia.")),
            (T("Is funded profit real money?","Le profit d’un compte financé, c’est de l’argent réel ?","¿El beneficio de una cuenta financiada es dinero real?"),
             T("Not until it’s paid out. Until then, it’s a balance on the firm’s account, under its rules.","Pas tant qu’il n’est pas payé. D’ici là, c’est un solde sur le compte de la firme, sous ses règles.","No hasta que se paga. Hasta entonces, es un saldo en la cuenta de la firma, bajo sus reglas.")),
            (T("When should I request my first payout?","Quand demander mon premier payout ?","¿Cuándo pedir mi primer payout?"),
             T("When your firm’s conditions are met and your own payout rule, written in advance, says so. Not on impulse after a good day.","Quand les conditions de ta firme sont remplies et que ta propre règle de payout, écrite d’avance, le dit. Pas sur un coup de tête après une bonne journée.","Cuando se cumplen las condiciones de tu firma y tu propia regla de payout, escrita de antemano, lo dice. No por impulso después de un buen día."))]
    return _sat_page(lang, t, T("Funded account","Compte financé","Cuenta financiada"),
        T("Passed? Now protect the funded account.","Réussi ? Maintenant, protège le compte financé.","¿Aprobaste? Ahora protege la cuenta financiada."),
        T("Funded accounts are often lost by traders who change what got them there. Five rules and a payout rule, written before you need them.",
          "Les comptes financés se perdent souvent quand le trader change ce qui l’a mené là. Cinq règles et une règle de payout, écrites avant d’en avoir besoin.",
          "Las cuentas financiadas se pierden a menudo cuando el trader cambia lo que lo llevó hasta ahí. Cinco reglas y una regla de payout, escritas antes de necesitarlas."),
        body, faqs, [GP_MONTHS[2], "prop-firm-payout-rules.html", "payout-tracker.html"],
        T("Funded Account Playbook: What to Do After You Pass · Sweep","Compte financé : le playbook après la réussite · Sweep","Cuenta financiada: el playbook tras aprobar · Sweep"),
        T("Passed your prop firm evaluation? Five rules to keep the funded account, a payout rule written in advance, and why funded profit isn’t income yet.",
          "Évaluation prop firm réussie ? Cinq règles pour garder le compte financé, une règle de payout écrite d’avance, et pourquoi ce profit n’est pas encore un revenu.",
          "¿Aprobaste tu evaluación de prop firm? Cinco reglas para conservar la cuenta financiada, una regla de payout escrita de antemano y por qué ese beneficio aún no es un ingreso."),
        "signup_gameplan_funded")

# ---- the liquidity sweep setup, with two diagrams drawn here (no platform screenshot)
SV_LABELS = {"pdl": T("PDL","PDL","PDL"), "sweep": T("Sweep","Sweep","Sweep"), "reclaim": T("Reclaim · entry","Retour · entrée","Recuperación · entrada"),
             "stop": T("Stop","Stop","Stop"), "target": T("Target · 2R","Cible · 2R","Objetivo · 2R"), "break": T("Closes and holds below: a breakout. Skip it.","Clôture et tient en dessous : une cassure. Passe ton tour.","Cierra y se mantiene por debajo: una ruptura. Déjalo pasar.")}

def _sweep_svg(t, kind):
    """Candles in price units (open, high, low, close), drawn on a 640 × 280 canvas. « long »: PDL swept then reclaimed; « break »: closes and holds below."""
    W, H_, lo, hi = 640, 280, 92.0, 114.0
    y = lambda p: round(24 + (hi - p) / (hi - lo) * (H_ - 48), 1)
    if kind == "long":
        cs = [(106, 107, 103.5, 104), (104, 104.5, 101.5, 102), (102, 102.5, 99.5, 100.5), (100.5, 101, 96.5, 97.5), (97.5, 101.8, 97, 101.5), (101.5, 104, 101, 103.5), (103.5, 107.5, 103, 107), (107, 113, 106.5, 112.5)]
    else:
        cs = [(106, 107, 103.5, 104), (104, 104.5, 101.5, 102), (102, 102.5, 99.5, 100.5), (100.5, 101, 97, 97.5), (97.5, 99.6, 96.5, 97), (97, 97.5, 94.5, 95), (95, 96.5, 93.5, 94)]
    x0, step, bw = 120, 56, 22
    out = [f'<line x1="40" x2="{W - 20}" y1="{y(100)}" y2="{y(100)}" class="lv"/><text x="40" y="{y(100) - 8}" class="lb">{t(SV_LABELS["pdl"])}</text>']
    for i, (o, h, l, c) in enumerate(cs):
        cx = x0 + i * step; up = c >= o
        out.append(f'<line x1="{cx}" x2="{cx}" y1="{y(h)}" y2="{y(l)}" class="wk {"up" if up else "dn"}"/>'
                   f'<rect x="{cx - bw / 2}" y="{min(y(o), y(c))}" width="{bw}" height="{max(2, abs(y(o) - y(c)))}" rx="3" class="bd {"up" if up else "dn"}"/>')
    if kind == "long":
        ex, ent, stop = x0 + 4 * step, 101.5, 96.0
        tgt = ent + 2 * (ent - stop)
        out.append(f'<text x="{x0 + 3 * step}" y="{y(96.5) + 20}" text-anchor="middle" class="lb">{t(SV_LABELS["sweep"])}</text>'
                   f'<line x1="{ex - 30}" x2="{W - 20}" y1="{y(stop)}" y2="{y(stop)}" class="st"/><text x="{W - 20}" y="{y(stop) + 16}" text-anchor="end" class="lb st-t">{t(SV_LABELS["stop"])}</text>'
                   f'<line x1="{ex}" x2="{W - 20}" y1="{y(tgt)}" y2="{y(tgt)}" class="tg"/><text x="{ex}" y="{y(tgt) - 8}" class="lb tg-t">{t(SV_LABELS["target"])}</text>'
                   f'<circle cx="{ex + bw / 2 + 6}" cy="{y(ent)}" r="5" class="en"/>'
                   f'<text x="{ex}" y="{y(101.8) - 10}" text-anchor="middle" class="lb rc">{t(SV_LABELS["reclaim"])}</text>')
        label = T("Long after a sweep of the previous day’s low: price trades below PDL, a 5-minute candle closes back above it, entry at its close, stop a few ticks under the sweep, target at 2R.",
                  "Achat après un sweep du plus bas de la veille : le prix passe sous le PDL, une bougie de 5 minutes clôture de nouveau au-dessus, entrée à sa clôture, stop quelques ticks sous le sweep, cible à 2R.",
                  "Compra tras un sweep del mínimo del día anterior: el precio cotiza por debajo del PDL, una vela de 5 minutos cierra de nuevo por encima, entrada a su cierre, stop unos ticks bajo el sweep, objetivo a 2R.")
    else:
        out.append(f'<text x="{W - 20}" y="{y(111)}" text-anchor="end" class="lb br-t">{t(SV_LABELS["break"])}</text>')
        label = T("Not a sweep: price closes below PDL and holds there. That’s a breakout, so there’s no trade.","Pas un sweep : le prix clôture sous le PDL et y reste. C’est une cassure, donc pas de trade.","No es un sweep: el precio cierra por debajo del PDL y se mantiene. Es una ruptura, así que no hay operación.")
    return (f'<figure class="gp-fig"><svg viewBox="0 0 {W} {H_}" role="img" aria-label="{html.escape(t(label))}">{"".join(out)}</svg>'
            f'<figcaption class="cap">{t(label)}</figcaption></figure>')

def page_gp_sweep(lang, t):
    """The liquidity sweep, explained (brief of Oct 19: « sweep trading » is mostly searched for this move, and it's where the name comes from):
    the concept first, then the Sweep Setup to practice it, then how to journal it."""
    H = lambda x: f"<h2>{t(x)}</h2>"
    body = (H(T("Buy-side and sell-side sweeps","Sweep côté acheteurs et côté vendeurs","Sweep del lado comprador y del lado vendedor"))
            + f'<p>{t(T("A buy-side sweep runs above a high, where buy stops and breakout buy orders sit, then falls back. A sell-side sweep runs below a low, where sell stops sit, then climbs back. In both cases, the orders beyond the level get filled and price fails to continue.","Un sweep côté acheteurs passe au-dessus d’un plus haut, là où sont les stops d’achat et les ordres d’achat sur cassure, puis retombe. Un sweep côté vendeurs passe sous un plus bas, là où sont les stops de vente, puis remonte. Dans les deux cas, les ordres au-delà du niveau sont exécutés et le prix ne continue pas.","Un sweep del lado comprador supera un máximo, donde están los stops de compra y las órdenes de compra por ruptura, y luego cae. Un sweep del lado vendedor pasa por debajo de un mínimo, donde están los stops de venta, y luego sube. En los dos casos, las órdenes más allá del nivel se ejecutan y el precio no continúa."))}</p>'
            + H(T("Where liquidity sits","Où se trouve la liquidité","Dónde está la liquidez")) + _ul(t, [
                T("The previous day’s high and low (<a href=\"@glossary.html#pdh-pdl\">PDH and PDL</a>).","Le plus haut et le plus bas de la veille (<a href=\"@glossary.html#pdh-pdl\">PDH et PDL</a>).","El máximo y el mínimo del día anterior (<a href=\"@glossary.html#pdh-pdl\">PDH y PDL</a>)."),
                T("The overnight session’s high and low, and the first range after the open.","Le plus haut et le plus bas de la séance de nuit, et le premier range après l’ouverture.","El máximo y el mínimo de la sesión nocturna, y el primer rango tras la apertura."),
                T("Round numbers, like 21,000 on NQ.","Les chiffres ronds, comme 21 000 sur le NQ.","Los números redondos, como 21.000 en el NQ."),
                T("Equal highs or equal lows: two or three touches at the same price.","Les plus hauts ou plus bas égaux : deux ou trois touches au même prix.","Máximos o mínimos iguales: dos o tres toques al mismo precio.")])
            + H(T("A sweep, step by step","Un sweep, étape par étape","Un sweep, paso a paso")) + _sweep_svg(t, "long")
            + _ol(t, [T("Before the session, mark the previous day’s low.","Avant la séance, trace le plus bas de la veille.","Antes de la sesión, marca el mínimo del día anterior."),
                      T("During the session, price trades below it: the stops beyond it are triggered.","Pendant la séance, le prix passe en dessous : les stops au-delà sont déclenchés.","Durante la sesión, el precio cotiza por debajo: los stops más allá se activan."),
                      T("A 5-minute candle closes back above the level: the move failed to continue.","Une bougie de 5 minutes clôture de nouveau au-dessus du niveau : le mouvement n’a pas continué.","Una vela de 5 minutos cierra de nuevo por encima del nivel: el movimiento no continuó."),
                      T("That close is the trigger of the Sweep Setup below. Sample data: no recommendation.","Cette clôture est le déclencheur du Sweep Setup plus bas. Données d’exemple : aucune recommandation.","Ese cierre es el disparador del Sweep Setup de abajo. Datos de ejemplo: ninguna recomendación.")])
            + H(T("Sweep or break of structure?","Sweep ou cassure de structure ?","¿Sweep o ruptura de estructura?")) + f'<p>{t(T("A break of structure is the opposite: price closes beyond the level and holds there, and the next pullback respects it. If the candle closes back inside, it’s a sweep. If it closes and holds beyond, it’s a break: no sweep trade.","Une cassure de structure, c’est l’inverse : le prix clôture au-delà du niveau et y reste, et le repli suivant le respecte. Si la bougie clôture de nouveau à l’intérieur, c’est un sweep. Si elle clôture et tient au-delà, c’est une cassure : pas de trade de sweep.","Una ruptura de estructura es lo contrario: el precio cierra más allá del nivel y se mantiene, y el siguiente retroceso lo respeta. Si la vela cierra de nuevo dentro, es un sweep. Si cierra y se mantiene más allá, es una ruptura: no hay operación de sweep."))}</p>' + _sweep_svg(t, "break")
            + H(T("Common mistakes","Les erreurs fréquentes","Los errores frecuentes")) + _ul(t, [
                T("Calling every wick a sweep: wait for the close back inside the level.","Voir un sweep dans chaque mèche : attends la clôture de retour à l’intérieur du niveau.","Ver un sweep en cada mecha: espera el cierre de vuelta dentro del nivel."),
                T("Entering before the reclaim candle has closed.","Entrer avant que la bougie de retour ait clôturé.","Entrar antes de que cierre la vela de recuperación."),
                T("Forgetting the economic calendar: a release can sweep a level both ways in seconds.","Oublier le calendrier économique : une annonce peut balayer un niveau dans les deux sens en quelques secondes.","Olvidar el calendario económico: un dato puede barrer un nivel en los dos sentidos en segundos."),
                T("A stop placed inside the noise, right at the extreme of the sweep.","Un stop placé dans le bruit, juste à l’extrême du sweep.","Un stop dentro del ruido, justo en el extremo del sweep."),
                T("Trading every sweep of the day instead of the ones in your window.","Trader chaque sweep de la journée au lieu de ceux de ta fenêtre.","Operar cada sweep del día en lugar de los de tu ventana.")])
            + H(T("A simple setup to practice it: the Sweep Setup","Un setup simple pour le pratiquer : le Sweep Setup","Un setup sencillo para practicarlo: el Sweep Setup"))
            + f'<p>{t(T("The setup of Month 1 of the <a href=\"@how-to-start-prop-firm-trading.html\">90-day gameplan</a>: the previous day’s high or low, a 5-minute reclaim, a fixed 2R target (see <a href=\"@glossary.html#r-multiple\">R multiple</a>).","Le setup du mois 1 du <a href=\"@how-to-start-prop-firm-trading.html\">plan de 90 jours</a> : le plus haut ou le plus bas de la veille, un retour sur 5 minutes, une cible fixe à 2R (voir <a href=\"@glossary.html#r-multiple\">R multiple</a>).","El setup del mes 1 del <a href=\"@how-to-start-prop-firm-trading.html\">plan de 90 días</a>: el máximo o el mínimo del día anterior, una recuperación en 5 minutos, un objetivo fijo a 2R (mira <a href=\"@glossary.html#r-multiple\">múltiplo R</a>)."))}</p>' + _tbl(t, SETUP)
            + f'<p>{t(T("Calculate the risk before you click: on MNQ, a 25-point stop is $50 on 1 micro; on MES, a 10-point stop is $50. If the stop is bigger than your max risk with 1 micro, skip it. Not sure which micro to use? See <a href=\"@mes-vs-mnq.html\">MES or MNQ</a>.","Calcule le risque avant de cliquer : sur le MNQ, un stop de 25 points vaut 50 $ avec 1 micro ; sur le MES, un stop de 10 points vaut 50 $. Si le stop dépasse ton risque max avec 1 micro, passe ton tour. Tu hésites entre les deux ? Voir <a href=\"@mes-vs-mnq.html\">MES ou MNQ</a>.","Calcula el riesgo antes de hacer clic: en el MNQ, un stop de 25 puntos son 50 $ con 1 micro; en el MES, un stop de 10 puntos son 50 $. Si el stop supera tu riesgo máximo con 1 micro, déjalo pasar. ¿Dudas entre los dos? Mira <a href=\"@mes-vs-mnq.html\">MES o MNQ</a>."))}</p>'
            + _ul(t, [T("<b>Train it in replay first:</b> 5 past days with PDH and PDL marked, 10 historical setups (failures included), 5 lookalikes that break a rule.","<b>Entraîne-le d’abord en replay :</b> 5 journées passées avec PDH et PDL tracés, 10 setups passés (échecs compris), 5 sosies qui brisent une règle.","<b>Entrénalo primero en replay:</b> 5 días pasados con PDH y PDL marcados, 10 setups pasados (fallos incluidos), 5 parecidos que rompen una regla."),
                      T("<b>Grade each one:</b> A when every criterion is clean, B when it’s valid but messy.","<b>Note chacun :</b> A quand chaque critère est net, B quand c’est valide mais brouillon.","<b>Califica cada uno:</b> A cuando cada criterio está limpio, B cuando es válido pero confuso.")])
            + H(T("How to journal sweep setups","Comment journaliser tes setups de sweep","Cómo registrar tus setups de sweep")) + _ul(t, [
                T("Log every sweep you take or pass, with a screenshot of the level and the reclaim.","Note chaque sweep que tu prends ou que tu passes, avec une capture du niveau et du retour.","Anota cada sweep que tomas o dejas pasar, con una captura del nivel y de la recuperación."),
                T("In Sweep, give those trades the setup “Sweep” and tag the level (PDH or PDL) and the time block.","Dans Sweep, donne à ces trades le setup « Sweep » et étiquette le niveau (PDH ou PDL) et le bloc horaire.","En Sweep, da a esas operaciones el setup «Sweep» y etiqueta el nivel (PDH o PDL) y el bloque horario."),
                T("After 20 to 30 trades, compare your results by setup and by tag. Edge Reveal points out your most profitable setup in R, and your coach tells you when a trade is in your edge.","Après 20 à 30 trades, compare tes résultats par setup et par étiquette. Edge Reveal te montre ton setup le plus rentable en R, et ton coach te dit quand un trade est dans ton edge.","Tras 20 a 30 operaciones, compara tus resultados por setup y por etiqueta. Edge Reveal te muestra tu setup más rentable en R, y tu coach te dice cuándo una operación está en tu edge.")])
            + f'<p>{t(T("Everything Sweep does with your trades is on the <a href=\"@features.html\">features page</a>.","Tout ce que Sweep fait avec tes trades est sur la <a href=\"@features.html\">page des fonctionnalités</a>.","Todo lo que Sweep hace con tus operaciones está en la <a href=\"@features.html\">página de funciones</a>."))}</p>'
            + _note(t, T("Why we’re called Sweep","Pourquoi on s’appelle Sweep","Por qué nos llamamos Sweep"), T("The name comes from this move: price sweeps a level, then turns. In trading as in a journal, the swept low is where the next move starts: that’s <a href=\"@index.html\">Sweep, the trading journal</a>.","Le nom vient de ce mouvement : le prix balaie un niveau, puis tourne. En trading comme dans un journal, le creux balayé est là où le prochain mouvement commence : c’est <a href=\"@index.html\">Sweep, le journal de trading</a>.","El nombre viene de este movimiento: el precio barre un nivel y luego gira. En el trading como en un diario, el mínimo barrido es donde empieza el siguiente movimiento: eso es <a href=\"@index.html\">Sweep, el diario de trading</a>.")))
    faqs = [(T("What is a liquidity sweep in trading?","Qu’est-ce qu’un liquidity sweep en trading ?","¿Qué es un liquidity sweep en trading?"),
             T("A move beyond an obvious high or low that triggers the stops resting just beyond it, then turns back the other way instead of continuing.","Un mouvement au-delà d’un plus haut ou d’un plus bas évident, qui déclenche les stops placés juste derrière, puis repart dans l’autre sens au lieu de continuer.","Un movimiento más allá de un máximo o un mínimo evidente que activa los stops situados justo detrás y luego vuelve en sentido contrario en lugar de continuar.")),
            (T("What’s the difference between a buy-side and a sell-side sweep?","Quelle différence entre un sweep côté acheteurs et côté vendeurs ?","¿Qué diferencia hay entre un sweep del lado comprador y del lado vendedor?"),
             T("A buy-side sweep runs above a high, through the buy stops, then falls back. A sell-side sweep runs below a low, through the sell stops, then climbs back.","Un sweep côté acheteurs passe au-dessus d’un plus haut, à travers les stops d’achat, puis retombe. Un sweep côté vendeurs passe sous un plus bas, à travers les stops de vente, puis remonte.","Un sweep del lado comprador supera un máximo, a través de los stops de compra, y luego cae. Un sweep del lado vendedor pasa por debajo de un mínimo, a través de los stops de venta, y luego sube.")),
            (T("Is a liquidity sweep the same as a stop hunt?","Un liquidity sweep, est-ce la même chose qu’une chasse aux stops ?","¿Un liquidity sweep es lo mismo que una caza de stops?"),
             T("Traders often use both words for the same move: price runs the stops beyond a level, then turns. Your journal only needs the facts: the level, the run, the reclaim.","Les traders emploient souvent les deux mots pour le même mouvement : le prix va chercher les stops au-delà d’un niveau, puis tourne. Ton journal n’a besoin que des faits : le niveau, le dépassement, le retour.","Los traders suelen usar las dos palabras para el mismo movimiento: el precio va a por los stops más allá de un nivel y luego gira. Tu diario solo necesita los hechos: el nivel, la ruptura, la recuperación.")),
            (T("What do PDH and PDL mean?","Que veulent dire PDH et PDL ?","¿Qué significan PDH y PDL?"),
             T("The previous day’s high and low. They’re marked before the session and don’t move during the day.","Le plus haut et le plus bas de la veille. On les trace avant la séance et ils ne bougent pas pendant la journée.","El máximo y el mínimo del día anterior. Se marcan antes de la sesión y no se mueven durante el día.")),
            (T("Which timeframe confirms the sweep?","Quelle unité de temps confirme le sweep ?","¿Qué marco temporal confirma el sweep?"),
             T("In the Sweep Setup, a 5-minute candle: it has to close back inside the level. Entry is at the close of that candle.","Dans le Sweep Setup, une bougie de 5 minutes : elle doit clôturer de nouveau à l’intérieur du niveau. L’entrée se fait à la clôture de cette bougie.","En el Sweep Setup, una vela de 5 minutos: debe cerrar de nuevo dentro del nivel. La entrada es al cierre de esa vela.")),
            (T("Is trading liquidity sweeps profitable?","Trader les liquidity sweeps, est-ce rentable ?","¿Operar liquidity sweeps es rentable?"),
             T("Nothing guarantees it. Whether sweeps work for you is something only your own tagged trades can show, over many trades.","Rien ne le garantit. Seuls tes propres trades étiquetés, sur beaucoup de trades, peuvent montrer si les sweeps marchent pour toi.","Nada lo garantiza. Solo tus propias operaciones etiquetadas, en muchas operaciones, pueden mostrar si los sweeps funcionan para ti."))]
    return _sat_page(lang, t, T("Trading concept","Notion de trading","Concepto de trading"),
        T("What is a liquidity sweep in trading?","Qu’est-ce qu’un liquidity sweep en trading ?","¿Qué es un liquidity sweep en trading?"),
        T("A liquidity sweep is when price runs past an obvious high or low, triggers the stops resting just beyond it, then turns back the other way. Here is how to spot one, how it differs from a break of structure, a simple setup to practice it and how to journal it.",
          "Un liquidity sweep, c’est quand le prix dépasse un plus haut ou un plus bas évident, déclenche les stops placés juste derrière, puis repart dans l’autre sens. Voici comment le repérer, ce qui le distingue d’une cassure de structure, un setup simple pour le pratiquer et comment le journaliser.",
          "Un liquidity sweep es cuando el precio supera un máximo o un mínimo evidente, activa los stops situados justo detrás y luego vuelve en sentido contrario. Aquí tienes cómo detectarlo, en qué se diferencia de una ruptura de estructura, un setup sencillo para practicarlo y cómo registrarlo."),
        body, faqs, ["glossary.html", GP_MICRO, GP_MONTHS[0]],
        T("Liquidity Sweep in Trading, Explained · Sweep","Le liquidity sweep en trading, expliqué · Sweep","El liquidity sweep en trading, explicado · Sweep"),
        T("What a liquidity sweep is in trading: buy-side and sell-side sweeps, where liquidity sits, sweep vs break of structure, and how to journal sweep setups.",
          "Le liquidity sweep en trading : côté acheteurs et vendeurs, où est la liquidité, sweep ou cassure de structure, et comment journaliser tes setups de sweep.",
          "El liquidity sweep en trading: lado comprador y vendedor, dónde está la liquidez, sweep o ruptura de estructura y cómo registrar tus setups de sweep."),
        "signup_liquidity_sweep")

# ---- MES or MNQ (specs from the contract data, pages12.py)
def page_gp_micro(lang, t):
    H = lambda x: f"<h2>{t(x)}</h2>"
    from pages18 import usd
    num = lambda v: f"{v:g}" if lang == "en" else f"{v:g}".replace(".", ",")
    rows = [(T("Index","Indice","Índice"), "S&P 500", "Nasdaq‑100"),
            (T("Tick size","Taille du tick","Tamaño del tick"), num(0.25), num(0.25)),
            (T("Tick value","Valeur du tick","Valor del tick"), usd(1.25, lang), usd(0.5, lang)),
            (T("Point value","Valeur du point","Valor del punto"), usd(5, lang), usd(2, lang)),
            (T("Its mini (10 micros)","Son mini (10 micros)","Su mini (10 micros)"), "ES", "NQ"),
            (T("Exchange","Bourse","Bolsa"), "CME", "CME")]
    tbl = ('<div class="cmp-wrap"><table class="cmp"><thead><tr><th scope="col"><span class="sr">' + t(T("Spec","Spécification","Especificación")) + '</span></th><th scope="col"><a href="@contracts/mes-futures.html">MES</a></th><th scope="col"><a href="@contracts/mnq-futures.html">MNQ</a></th></tr></thead><tbody>'
           + "".join(f'<tr><th scope="row">{t(a)}</th><td>{b if isinstance(b, str) else t(b)}</td><td>{c if isinstance(c, str) else t(c)}</td></tr>' for a, b, c in rows) + "</tbody></table></div>")
    body = (H(T("Side by side","Côte à côte","Lado a lado")) + tbl
            + H(T("Same dollars, different points","Mêmes dollars, points différents","Mismos dólares, distintos puntos")) + f'<p>{t(T("With $50 of risk per trade on 1 micro: a 10-point stop on MES, a 25-point stop on MNQ. The Nasdaq-100 is quoted at a higher level and usually moves more points in a session, so MNQ stops are wider in points, but each point is worth less.","Avec 50 $ de risque par trade sur 1 micro : un stop de 10 points sur le MES, un stop de 25 points sur le MNQ. Le Nasdaq-100 est coté à un niveau plus élevé et bouge généralement de plus de points dans une séance : les stops du MNQ sont donc plus larges en points, mais chaque point vaut moins.","Con 50 $ de riesgo por operación con 1 micro: un stop de 10 puntos en el MES, un stop de 25 puntos en el MNQ. El Nasdaq-100 cotiza a un nivel más alto y suele moverse más puntos en una sesión, así que los stops del MNQ son más amplios en puntos, pero cada punto vale menos."))}</p>'
            + H(T("Which one to pick","Lequel choisir","Cuál elegir")) + _ul(t, [T("<b>Pick the chart you read best.</b> Watch both for a few sessions in your window before you choose.","<b>Choisis le graphique que tu lis le mieux.</b> Observe les deux pendant quelques séances dans ta fenêtre avant de choisir.","<b>Elige el gráfico que mejor lees.</b> Observa los dos durante unas sesiones en tu ventana antes de elegir."),
                T("<b>Then keep it.</b> One market for 90 days: switching resets your sample and your skip list.","<b>Puis garde-le.</b> Un marché pendant 90 jours : changer remet à zéro ton échantillon et ta liste de setups à passer.","<b>Y quédate con él.</b> Un mercado durante 90 días: cambiar reinicia tu muestra y tu lista de setups que dejar pasar."),
                T("<b>Check your stop in dollars, not in points,</b> before every trade.","<b>Vérifie ton stop en dollars, pas en points,</b> avant chaque trade.","<b>Revisa tu stop en dólares, no en puntos,</b> antes de cada operación.")])
            + H(T("Fees count","Les frais comptent","Las comisiones cuentan")) + f'<p>{t(T("Commissions are charged per contract, so on a small stop they weigh more in R. Count them in your risk, and check your broker’s or your firm’s rates. The <a href=\"@position-size-calculator.html\">position size calculator</a> turns a stop in points into dollars for both.","Les commissions sont facturées par contrat : sur un petit stop, elles pèsent plus en R. Compte-les dans ton risque, et vérifie les tarifs de ton courtier ou de ta firme. Le <a href=\"@position-size-calculator.html\">calculateur de taille de position</a> convertit un stop en points en dollars pour les deux.","Las comisiones se cobran por contrato: con un stop pequeño, pesan más en R. Inclúyelas en tu riesgo y revisa las tarifas de tu bróker o de tu firma. La <a href=\"@position-size-calculator.html\">calculadora de tamaño de posición</a> convierte un stop en puntos a dólares para los dos."))}</p>')
    faqs = [(T("Is MES or MNQ better for beginners?","Le MES ou le MNQ est-il meilleur pour débuter ?","¿Es mejor el MES o el MNQ para principiantes?"),
             T("Neither is better in itself. Both are micros, a tenth of their mini; pick the one whose chart you read best, then keep it.","Aucun n’est meilleur en soi. Les deux sont des micros, un dixième de leur mini ; choisis celui dont tu lis le mieux le graphique, puis garde-le.","Ninguno es mejor en sí. Los dos son micros, una décima parte de su mini; elige el que mejor lees en el gráfico y quédate con él.")),
            (T("How much is one point on MNQ and MES?","Combien vaut un point sur le MNQ et le MES ?","¿Cuánto vale un punto en el MNQ y el MES?"),
             T("$2 on MNQ and $5 on MES, per contract. One tick (0.25 point) is $0.50 on MNQ and $1.25 on MES.","2 $ sur le MNQ et 5 $ sur le MES, par contrat. Un tick (0,25 point) vaut 0,50 $ sur le MNQ et 1,25 $ sur le MES.","2 $ en el MNQ y 5 $ en el MES, por contrato. Un tick (0,25 punto) vale 0,50 $ en el MNQ y 1,25 $ en el MES.")),
            (T("Can I trade both at the same time?","Puis-je trader les deux en même temps ?","¿Puedo operar los dos a la vez?"),
             T("The 90-day gameplan keeps one market, one window and one setup, so your data measures one thing at a time.","Le plan de 90 jours garde un marché, une fenêtre et un setup, pour que tes données mesurent une seule chose à la fois.","El plan de 90 días mantiene un mercado, una ventana y un setup, para que tus datos midan una sola cosa a la vez."))]
    return _sat_page(lang, t, T("Micro futures","Micro futures","Micro futuros"),
        T("MES or MNQ: which micro to start with?","MES ou MNQ : quel micro pour débuter ?","MES o MNQ: ¿con qué micro empezar?"),
        T("Both are a tenth of their mini, both move in 0.25-point ticks, both trade on CME. What changes is the value of a point, and so the size of your stop.",
          "Les deux valent un dixième de leur mini, les deux bougent par ticks de 0,25 point, les deux se négocient sur le CME. Ce qui change, c’est la valeur d’un point, donc la taille de ton stop.",
          "Los dos valen una décima parte de su mini, los dos se mueven en ticks de 0,25 puntos, los dos cotizan en el CME. Lo que cambia es el valor de un punto, y por tanto el tamaño de tu stop."),
        body, faqs, [GP_MONTHS[0], GP_SWEEP, "futures-contracts.html"],
        T("MES vs MNQ: Which Micro Future to Start With? · Sweep","MES ou MNQ : quel micro choisir pour débuter · Sweep","MES o MNQ: con qué micro empezar · Sweep"),
        T("MES vs MNQ for beginners: tick and point values, the same dollar risk in points on each, and how to choose one micro future and stick with it.",
          "MES ou MNQ pour débuter : valeurs du tick et du point, le même risque en dollars traduit en points sur chacun, et comment choisir un micro et le garder.",
          "MES o MNQ para principiantes: valores del tick y del punto, el mismo riesgo en dólares en puntos en cada uno, y cómo elegir un micro y quedarse con él."),
        "signup_gameplan_micro")

SYSTEM_PAGES.update(GP_SATS)
